#include "eips_private.h"

/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/

/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/
void eips_shutdown_timeout_start(void * arg)
{
  #define VARS  eips_vars

  if(timeout_test(VARS.timeout_shutdown) && VARS.option.enabled && !VARS.fail_status && VARS.rpm_status && !VARS.gwr_status && !VARS.skd_status && !VARS.door_status && !VARS.speed_status)   
    {
      timeout_start(eips_vars.timeout_shutdown) ;

      eips_alert_func            (0) ;  // Notify user + start timer

      #if DBG_EIPS == 1
        dbg_tx_text("\nEIPS Shutdown Timeout Start")  ;
      #endif    
    }

  #undef VARS              
}
